-- =====================================================================
-- PANGKALAN DATA SISTEM PENGURUSAN STOK & PERMOHONAN BORANG KEW.PS-8
-- PEJABAT KDYMM TUANKU SULTAN KEDAH DARUL AMAN
-- Skrip Skema Asas untuk phpMyAdmin / Laragon MySQL
-- =====================================================================
-- =====================================================================
-- PANGKALAN DATA SISTEM PENGURUSAN STOK & PERMOHONAN BORANG KEW.PS-8
-- PEJABAT KDYMM TUANKU SULTAN KEDAH DARUL AMAN
-- Skrip Skema Asas & Data 463 Item Lengkap untuk Laragon / phpMyAdmin
-- Mengelakkan pertindihan jadual atau data (ON DUPLICATE KEY UPDATE)
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `kewps8_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `kewps8_db`;

-- 1. Jadual Utama: `senarai data stok pejabat`
CREATE TABLE IF NOT EXISTS `senarai data stok pejabat` (
  `id` varchar(50) NOT NULL,
  `no_kad` int(11) DEFAULT NULL,
  `kod` varchar(30) NOT NULL,
  `nama` varchar(255) NOT NULL,
  `kategori` varchar(100) NOT NULL DEFAULT 'Alat Tulis',
  `unit` varchar(50) NOT NULL DEFAULT 'UNIT',
  `harga_seunit` decimal(10,2) NOT NULL DEFAULT 0.00,
  `baki_stok` int(11) NOT NULL DEFAULT 0,
  `paras_minimum` int(11) NOT NULL DEFAULT 5,
  `gambar` varchar(255) DEFAULT 'package',
  `catatan` text DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_kod_unique` (`kod`),
  KEY `idx_kategori` (`kategori`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Pandangan (Views) untuk keserasian sekiranya import berlaku pada nama lain
CREATE OR REPLACE VIEW `items` AS SELECT * FROM `senarai data stok pejabat`;
CREATE OR REPLACE VIEW `senarai_data_stok_pejabat` AS SELECT * FROM `senarai data stok pejabat`;

-- 2. Jadual: `requests` (Permohonan KEW.PS-8)
CREATE TABLE IF NOT EXISTS `requests` (
  `id` varchar(50) NOT NULL,
  `no_bpsi` varchar(50) NOT NULL UNIQUE,
  `nama_pemohon` varchar(150) NOT NULL,
  `jawatan` varchar(100) NOT NULL,
  `bahagian` varchar(150) NOT NULL,
  `tarikh_mohon` date NOT NULL,
  `status` enum('Menunggu Kelulusan', 'Diluluskan', 'Ditolak', 'Selesai Diambil') NOT NULL DEFAULT 'Menunggu Kelulusan',
  `catatan_pemohon` text DEFAULT NULL,
  `nama_pelulus` varchar(150) DEFAULT NULL,
  `jawatan_pelulus` varchar(100) DEFAULT NULL,
  `tarikh_kelulusan` date DEFAULT NULL,
  `catatan_pelulus` text DEFAULT NULL,
  `nama_penerima` varchar(150) DEFAULT NULL,
  `jawatan_penerima` varchar(100) DEFAULT NULL,
  `tarikh_terima` date DEFAULT NULL,
  `alasan_penolakan` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_no_bpsi` (`no_bpsi`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Jadual: `request_items` (Senarai Item yang Dimohon)
CREATE TABLE IF NOT EXISTS `request_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `request_id` varchar(50) NOT NULL,
  `item_id` varchar(50) NOT NULL,
  `kod` varchar(30) NOT NULL,
  `nama` varchar(255) NOT NULL,
  `unit` varchar(50) NOT NULL,
  `kuantiti_dimohon` int(11) NOT NULL DEFAULT 1,
  `kuantiti_diluluskan` int(11) DEFAULT NULL,
  `baki_sedia_ada` int(11) NOT NULL DEFAULT 0,
  `catatan` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_request_id` (`request_id`),
  CONSTRAINT `fk_request_items_req` FOREIGN KEY (`request_id`) REFERENCES `requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- MEMASUKKAN 463 DATA STOK PEJABAT SECARA TERUS (ON DUPLICATE KEY UPDATE)
-- =====================================================================

ON DUPLICATE KEY UPDATE 
  `no_kad` = VALUES(`no_kad`),
  `nama` = VALUES(`nama`),
  `kategori` = VALUES(`kategori`),
  `unit` = VALUES(`unit`),
  `harga_seunit` = VALUES(`harga_seunit`),
  `baki_stok` = VALUES(`baki_stok`);
